head.b:skin:
*, *::before, *::after { box-sizing:border-box; }
html { margin:0; padding:0; scroll-behavior:smooth; -webkit-text-size-adjust:100%; }
body { margin:0; padding:0; font-family:'Cairo',system-ui,-apple-system,'Segoe UI',Tahoma,Arial,sans-serif; background:#f1f5f4; color:#16241f; direction:rtl; text-align:right; line-height:1.9; font-size:16px; overflow-x:hidden; }
img { max-width:100%; height:auto; display:block; border:0; }
a { color:#0b8f4f; text-decoration:none; transition:color .25s ease, background .25s ease; }
a:hover { color:#00c76a; }
ul, ol { list-style:none; margin:0; padding:0; }
h1, h2, h3, h4 { margin:0 0 12px; line-height:1.5; font-weight:800; }
p { margin:0 0 14px; }
button, input, textarea, select { font-family:inherit; }
.container { max-width:1180px; margin:0 auto; padding:0 16px; width:100%; }
.section { padding:6px 0 22px; }
.hidden-section { display:none !important; height:0 !important; overflow:hidden !important; margin:0 !important; padding:0 !important; }
.site-header { background:linear-gradient(135deg,#0d2b21 0%,#103f2e 55%,#0b5c3c 100%); color:#fff; position:sticky; top:0; z-index:999; box-shadow:0 2px 16px rgba(0,0,0,.22); margin:0; padding:0; }
.header-inner { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:14px; min-height:76px; padding:8px 0; }
.brand { flex:0 0 auto; order:1; }
.brand-link { display:flex; align-items:center; gap:10px; color:#fff !important; font-weight:900; font-size:22px; letter-spacing:-.3px; }
.brand-text { white-space:nowrap; }
.main-nav { order:2; margin-inline-start:16px; margin-inline-end:auto; }
.nav-list { display:flex; align-items:center; gap:4px; flex-wrap:wrap; }
.nav-list a { display:block; padding:8px 15px; border-radius:9px; color:#dff5ea !important; font-weight:600; font-size:15px; white-space:nowrap; }
.nav-list a:hover { background:#00c76a; color:#052b1e !important; }
.nav-toggle { display:none; background:#00c76a; border:0; color:#04241a; font-size:20px; font-weight:700; border-radius:10px; width:44px; height:44px; cursor:pointer; margin-inline-start:auto; order:1; }
.search-form { order:3; display:flex; align-items:center; background:rgba(255,255,255,.10); border:1px solid rgba(0,199,106,.5); border-radius:30px; padding:3px; min-width:250px; }
.search-form:focus-within { border-color:#00c76a; background:rgba(255,255,255,.16); }
.search-form input { flex:1; min-width:0; border:0; outline:0; background:transparent; color:#fff; padding:8px 16px; font-size:14px; }
.search-form input::placeholder { color:#b9d8cc; }
.search-form button { border:0; cursor:pointer; background:#00c76a; color:#04241a; font-weight:700; padding:8px 18px; border-radius:24px; font-size:14px; }
.search-form button:hover { background:#05a85b; color:#fff; }
.section-head { display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap; margin:30px 0 18px; padding-bottom:10px; border-bottom:2px solid #e2ebe7; }
.section-title { font-size:22px; font-weight:800; color:#0d2b21; margin:0; display:flex; align-items:center; gap:10px; }
.section-title::before { content:''; width:6px; height:26px; border-radius:4px; background:linear-gradient(180deg,#00c76a,#0b8f4f); display:inline-block; }
.section-more { font-size:13.5px; font-weight:700; color:#0b8f4f; background:#e6f8ef; padding:6px 16px; border-radius:20px; }
.section-more:hover { background:#00c76a; color:#04241a; }
.cards-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(230px,1fr)); gap:18px; }
.card { background:#fff; border-radius:14px; overflow:hidden; box-shadow:0 6px 20px rgba(13,43,33,.08); transition:transform .3s ease, box-shadow .3s ease; display:flex; flex-direction:column; }
.card:hover { transform:translateY(-5px); box-shadow:0 16px 32px rgba(13,43,33,.16); }
.card-thumb { position:relative; display:block; width:100%; aspect-ratio:16/9; background:linear-gradient(135deg,#0d2b21,#0f5c3d); overflow:hidden; }
.card-img { width:100%; height:100%; object-fit:cover; transition:transform .45s ease; }
.card:hover .card-img { transform:scale(1.07); }
.card-noimg { position:absolute; inset:0; display:flex; align-items:center; justify-content:center; color:#00c76a; font-size:34px; opacity:.85; }
.card-body { padding:12px 14px 16px; flex:1; display:flex; flex-direction:column; }
.card-title { font-size:15.5px; font-weight:700; line-height:1.65; margin:0 0 8px; }
.card-title a { color:#12241d; }
.card-title a:hover { color:#00c76a; }
.card-meta { font-size:12.5px; color:#7b8f87; margin-top:auto; display:flex; align-items:center; gap:10px; flex-wrap:wrap; }
.card-meta .cmt { display:inline-flex; align-items:center; gap:4px; font-weight:600; color:#0b8f4f; }
.card-meta .cmt::before { content:'\1F4AC'; font-size:11px; }
.loading, .empty-msg { grid-column:1 / -1; text-align:center; color:#7b8f87; padding:28px 10px; font-size:14px; background:#fff; border-radius:14px; }
.main-content { padding:10px 16px 30px; }
.post-single { background:#fff; border-radius:16px; padding:26px; box-shadow:0 6px 24px rgba(13,43,33,.07); }
.post-title { font-size:28px; font-weight:900; color:#0d2b21; margin:0 0 14px; line-height:1.5; }
.post-title a { color:#0d2b21; }
.post-meta { display:flex; flex-wrap:wrap; gap:8px 14px; align-items:center; font-size:13px; color:#7b8f87; border-bottom:1px solid #eaf1ee; padding-bottom:14px; margin-bottom:20px; }
.post-meta a { background:#e6f8ef; color:#0b8f4f; padding:3px 12px; border-radius:20px; font-weight:600; margin-inline-start:6px; font-size:12.5px; }
.post-meta a:hover { background:#00c76a; color:#04241a; }
.post-body { font-size:17px; line-height:2; color:#22332c; word-wrap:break-word; overflow-wrap:break-word; }
.post-body img { border-radius:10px; margin:14px auto; }
.post-body h2, .post-body h3, .post-body h4 { color:#0d2b21; margin-top:26px; }
.post-body a { color:#0b8f4f; text-decoration:underline; }
.post-body ul, .post-body ol { padding-inline-start:22px; margin-bottom:14px; }
.post-body ul li { list-style:disc; }
.post-body ol li { list-style:decimal; }
.post-body blockquote { margin:18px 0; padding:14px 18px; background:#eefaf4; border-inline-start:5px solid #00c76a; border-radius:10px; color:#14523a; }
.post-body table { width:100%; border-collapse:collapse; margin:16px 0; }
.post-body td, .post-body th { border:1px solid #e2ebe7; padding:9px; text-align:right; }
.post-body th { background:#eefaf4; }
.youtube-container { position:relative; width:100%; padding-bottom:56.25%; height:0; overflow:hidden; margin:20px 0; border-radius:14px; background:#000; box-shadow:0 10px 26px rgba(13,43,33,.22); }
.youtube-container iframe, .youtube-container object, .youtube-container embed, .youtube-container video { position:absolute; top:0; left:0; width:100%; height:100%; border:0; }
.download-links { background:linear-gradient(135deg,#0d2b21 0%,#124a36 100%); border:1px solid rgba(0,199,106,.35); border-radius:16px; padding:20px; margin:26px 0; box-shadow:0 10px 26px rgba(13,43,33,.18); }
.download-links h3, .download-links .dl-title { color:#fff; font-size:18px; font-weight:800; margin:0 0 14px; display:flex; align-items:center; gap:10px; }
.download-links h3::before, .download-links .dl-title::before { content:'\2193'; width:32px; height:32px; border-radius:9px; background:#00c76a; color:#04241a; display:inline-flex; align-items:center; justify-content:center; font-size:16px; }
.download-links a { display:flex; align-items:center; justify-content:space-between; gap:12px; background:rgba(255,255,255,.07); color:#e8fff5 !important; border:1px solid rgba(0,199,106,.3); border-radius:11px; padding:12px 18px; margin-bottom:10px; font-weight:700; font-size:15px; transition:background .25s ease, transform .25s ease; }
.download-links a:last-child { margin-bottom:0; }
.download-links a:hover { background:#00c76a; color:#04241a !important; transform:translateX(-5px); border-color:#00c76a; }
.download-links a::after { content:'\2B07'; font-size:16px; }
.site-footer { background:#0d2b21; color:#a9c6ba; margin-top:44px; padding:30px 0 24px; text-align:center; font-size:14px; border-top:4px solid #00c76a; }
.site-footer a { color:#00c76a; font-weight:700; }
.site-footer a:hover { color:#fff; }
.footer-links { display:flex; justify-content:center; flex-wrap:wrap; gap:8px 18px; margin-bottom:12px; }
.footer-links a { color:#cfe9de; font-weight:600; }
.footer-links a:hover { color:#00c76a; }
.about-page .post-title { text-align:center; margin-bottom:8px; }
.about-page .post-title::after { content:''; display:block; width:70px; height:4px; background:linear-gradient(90deg,#00c76a,#0b8f4f); border-radius:4px; margin:12px auto 0; }
.yt-hero { background:linear-gradient(135deg,#0d2b21 0%,#124a36 100%); border-radius:16px; padding:26px; margin:24px 0; display:flex; align-items:center; gap:22px; flex-wrap:wrap; box-shadow:0 12px 32px rgba(13,43,33,.2); }
.yt-avatar { width:100px; height:100px; border-radius:50%; flex-shrink:0; background:linear-gradient(145deg,#00c76a,#06a458); color:#04241a; display:flex; align-items:center; justify-content:center; font-size:44px; font-weight:900; box-shadow:0 8px 22px rgba(0,199,106,.45), 0 0 0 4px rgba(0,199,106,.2); }
.yt-meta { flex:1; min-width:220px; }
.yt-meta h2 { color:#fff; margin:0 0 6px; font-size:26px; font-weight:900; }
.yt-meta .yt-handle { color:#00c76a; font-size:15px; font-weight:600; margin-bottom:10px; display:block; }
.yt-meta .yt-stats { color:#b9d8cc; font-size:14px; margin-bottom:16px; }
.yt-meta .yt-stats span { display:inline-block; margin-inline-end:16px; }
.yt-meta .yt-stats strong { color:#fff; font-weight:800; }
.yt-sub-btn { display:inline-flex; align-items:center; gap:8px; background:#00c76a; color:#04241a !important; padding:10px 22px; border-radius:26px; font-weight:800; font-size:15px; text-decoration:none !important; transition:transform .25s ease, background .25s ease, box-shadow .25s ease; box-shadow:0 6px 16px rgba(0,199,106,.35); }
.yt-sub-btn:hover { background:#05a85b; color:#fff !important; transform:translateY(-2px); box-shadow:0 10px 24px rgba(0,199,106,.5); }
.yt-sub-btn::before { content:'\25B6'; font-size:12px; }
.about-card { background:#f8fbf9; border-radius:14px; padding:24px; border-inline-start:5px solid #00c76a; font-size:16px; line-height:2; color:#22332c; margin-bottom:18px; }
.about-card h3 { color:#0d2b21; font-size:19px; margin:0 0 14px; display:flex; align-items:center; gap:10px; }
.about-card h3::before { content:''; width:6px; height:22px; border-radius:4px; background:linear-gradient(180deg,#00c76a,#0b8f4f); }
.about-list { list-style:none; padding:0; margin:16px 0; }
.about-list li { padding:12px 16px; margin-bottom:8px; background:#fff; border-radius:10px; font-size:15.5px; line-height:1.7; display:flex; align-items:center; gap:12px; box-shadow:0 2px 8px rgba(13,43,33,.05); transition:transform .25s ease; }
.about-list li:hover { transform:translateX(-5px); }
.about-list .ico { font-size:22px; flex-shrink:0; }
.about-card em { color:#0b8f4f; font-style:normal; font-weight:700; }
.about-quote { background:#eefaf4; padding:16px 20px; border-radius:10px; border-inline-start:4px solid #00c76a; color:#14523a; font-weight:600; margin:16px 0; }
.about-cta { text-align:center; padding:20px; background:linear-gradient(135deg,#0d2b21,#124a36); border-radius:14px; color:#fff; margin-top:20px; }
.about-cta p { color:#cfe9de; margin:0 0 14px; font-size:15px; }
.about-cta strong { color:#fff; }
.about-hashtags { display:flex; flex-wrap:wrap; gap:8px; justify-content:center; margin-top:18px; padding-top:18px; border-top:1px dashed rgba(0,199,106,.3); }
.about-hashtags span { background:rgba(0,199,106,.15); color:#00c76a; padding:5px 14px; border-radius:20px; font-size:13px; font-weight:600; }

/* ============ COMMENTS SECTION ============ */
.post-comments { margin-top:30px; padding-top:22px; border-top:2px solid #e2ebe7; }
.post-comments h3 { font-size:20px; font-weight:800; color:#0d2b21; margin:0 0 16px; display:flex; align-items:center; gap:10px; }
.post-comments h3::before { content:''; width:6px; height:22px; border-radius:4px; background:linear-gradient(180deg,#00c76a,#0b8f4f); }
.comments-cta { text-align:center; padding:34px 20px; background:#f8fbf9; border-radius:14px; border:1px dashed #c8d8d0; }
.comments-cta p { font-size:15px; color:#4a5a52; margin-bottom:18px; }
.comments-cta a.comments-btn { display:inline-flex; align-items:center; gap:10px; background:#00c76a; color:#04241a !important; padding:14px 32px; border-radius:28px; font-weight:800; font-size:16px; text-decoration:none !important; box-shadow:0 8px 20px rgba(0,199,106,.35); transition:transform .25s ease, background .25s ease, box-shadow .25s ease; }
.comments-cta a.comments-btn:hover { background:#05a85b; color:#fff !important; transform:translateY(-3px); box-shadow:0 12px 28px rgba(0,199,106,.5); }
.comments-cta a.comments-btn::before { content:'\1F4AC'; font-size:18px; }

.theme-toggle { order:4; background:rgba(255,255,255,.10); border:1px solid rgba(0,199,106,.5); color:#fff; width:42px; height:42px; border-radius:50%; cursor:pointer; font-size:18px; display:flex; align-items:center; justify-content:center; transition:background .25s ease, transform .25s ease; flex-shrink:0; padding:0; }
.theme-toggle:hover { background:#00c76a; color:#04241a; transform:scale(1.05); }
.theme-toggle::before { content:'\1F319'; font-size:20px; line-height:1; }
body.dark-mode .theme-toggle::before { content:'\2600\FE0F'; }

.scroll-top { position:fixed; bottom:24px; left:24px; width:48px; height:48px; border-radius:50%; background:linear-gradient(145deg,#00c76a,#06a458); color:#04241a; border:0; cursor:pointer; display:flex; align-items:center; justify-content:center; font-size:22px; font-weight:900; box-shadow:0 8px 22px rgba(0,199,106,.45); opacity:0; visibility:hidden; transform:translateY(10px); transition:opacity .3s ease, transform .3s ease, visibility .3s; z-index:998; padding:0; }
.scroll-top.show { opacity:1; visibility:visible; transform:translateY(0); }
.scroll-top:hover { transform:translateY(-3px) scale(1.05); box-shadow:0 12px 28px rgba(0,199,106,.55); }
.scroll-top::before { content:'\2191'; line-height:1; }

/* ============ DARK MODE — FIX LIGHT BOXES INSIDE POSTS ============ */
body.dark-mode .post-body [style*="background:#f"],
body.dark-mode .post-body [style*="background: #f"],
body.dark-mode .post-body [style*="background:#e"],
body.dark-mode .post-body [style*="background: #e"],
body.dark-mode .post-body [style*="background:#d"],
body.dark-mode .post-body [style*="background: #d"],
body.dark-mode .post-body [style*="background-color:#f"],
body.dark-mode .post-body [style*="background-color: #f"],
body.dark-mode .post-body [style*="background-color:#e"],
body.dark-mode .post-body [style*="background-color: #e"],
body.dark-mode .post-body [style*="background-color:#d"],
body.dark-mode .post-body [style*="background-color: #d"],
body.dark-mode .post-body [style*="background:#FFF"],
body.dark-mode .post-body [style*="background: #FFF"],
body.dark-mode .post-body [style*="background:#fff"],
body.dark-mode .post-body [style*="background: #fff"],
body.dark-mode .post-body [style*="background:white"],
body.dark-mode .post-body [style*="background: white"],
body.dark-mode .post-body [style*="background:rgb(2"],
body.dark-mode .post-body [style*="background: rgb(2"],
body.dark-mode .post-body [style*="background-color:rgb(2"],
body.dark-mode .post-body [style*="background-color: rgb(2"] {
  background:#4a4a48 !important;
  color:#e8e6e3 !important;
  border-color:#565654 !important;
}

body.dark-mode .post-body [style*="background:#00c76a"],
body.dark-mode .post-body [style*="background: #00c76a"],
body.dark-mode .post-body [style*="background:#0b8f4f"],
body.dark-mode .post-body [style*="background: #0b8f4f"] {
  background:#0d4a32 !important;
  color:#e8e6e3 !important;
}

body.dark-mode .post-body [style*="color:#1"],
body.dark-mode .post-body [style*="color: #1"],
body.dark-mode .post-body [style*="color:#0"],
body.dark-mode .post-body [style*="color: #0"],
body.dark-mode .post-body [style*="color:#2"],
body.dark-mode .post-body [style*="color: #2"],
body.dark-mode .post-body [style*="color:#3"],
body.dark-mode .post-body [style*="color: #3"],
body.dark-mode .post-body [style*="color:black"],
body.dark-mode .post-body [style*="color: black"],
body.dark-mode .post-body [style*="color:#4"],
body.dark-mode .post-body [style*="color: #4"] {
  color:#e8e6e3 !important;
}

/* ============ DARK MODE — BATTLESHIP GRAY ============ */
body { transition:background-color .35s ease, color .35s ease; }
body.dark-mode { background:#3d3d3b; color:#e8e6e3; }

body.dark-mode .site-header { background:linear-gradient(135deg,#1f2823 0%,#2b3a33 55%,#1d3329 100%); box-shadow:0 2px 16px rgba(0,0,0,.4); }
body.dark-mode .brand-text { color:#f0ede8 !important; }
body.dark-mode .nav-list a { color:#d4d2cd !important; }
body.dark-mode .nav-list a:hover { background:#00c76a; color:#04241a !important; }
body.dark-mode .search-form { background:rgba(255,255,255,.06); border-color:rgba(0,199,106,.35); }
body.dark-mode .search-form input { color:#e8e6e3; }
body.dark-mode .search-form input::placeholder { color:#8a8885; }

body.dark-mode .section-head { border-bottom-color:#4a4a48; }
body.dark-mode .section-title { color:#f0ede8; }
body.dark-mode .section-more { background:#4a4a48; color:#00c76a; }
body.dark-mode .section-more:hover { background:#00c76a; color:#04241a; }

body.dark-mode .card, body.dark-mode .post-single { background:#4a4a48; border:1px solid #565654; box-shadow:0 6px 20px rgba(0,0,0,.3); }
body.dark-mode .card:hover { box-shadow:0 16px 32px rgba(0,0,0,.45); }
body.dark-mode .card-thumb { background:linear-gradient(135deg,#2a2a28,#3a3a38); }
body.dark-mode .card-title a { color:#f0ede8; }
body.dark-mode .card-title a:hover { color:#00c76a; }
body.dark-mode .card-meta { color:#a8a5a0; }
body.dark-mode .card-meta .cmt { color:#00c76a; }

body.dark-mode .post-title, body.dark-mode .post-title a { color:#f0ede8; }
body.dark-mode .post-meta { color:#a8a5a0; border-bottom-color:#565654; }
body.dark-mode .post-meta a { background:#565654; color:#00c76a; }
body.dark-mode .post-body { color:#dedbd6; }
body.dark-mode .post-body h2, body.dark-mode .post-body h3, body.dark-mode .post-body h4 { color:#f0ede8; }
body.dark-mode .post-body a { color:#00c76a; }
body.dark-mode .post-body blockquote { background:#3d3d3b; color:#c8e6d5; border-inline-start-color:#00c76a; }
body.dark-mode .post-body td, body.dark-mode .post-body th { border-color:#565654; }
body.dark-mode .post-body th { background:#3d3d3b; }

body.dark-mode .post-comments { border-top-color:#565654; }
body.dark-mode .post-comments h3 { color:#f0ede8; }
body.dark-mode .comments-cta { background:#3d3d3b; border-color:#565654; }
body.dark-mode .comments-cta p { color:#a8a5a0; }

body.dark-mode .loading, body.dark-mode .empty-msg { background:#4a4a48; color:#a8a5a0; border:1px solid #565654; }

body.dark-mode .site-footer { background:#2a2a28; color:#a8a5a0; border-top-color:#00c76a; }
body.dark-mode .footer-links a { color:#d4d2cd; }

body.dark-mode .about-card { background:#4a4a48; color:#dedbd6; border:1px solid #565654; border-inline-start:5px solid #00c76a; }
body.dark-mode .about-card h3 { color:#f0ede8; }
body.dark-mode .about-card em { color:#00c76a; }
body.dark-mode .about-list li { background:#3d3d3b; color:#dedbd6; border:1px solid #4a4a48; }
body.dark-mode .about-quote { background:#3d3d3b; color:#c8e6d5; }
body.dark-mode .yt-hero { background:linear-gradient(135deg,#2a2a28 0%,#3a3a38 100%); }

@media (max-width:900px) {
  .header-inner {
    flex-wrap: wrap;
    justify-content: flex-start;
    gap: 6px;
    padding: 8px 0;
  }
  .brand { order: 1; flex: 0 0 auto; margin: 0; margin-inline-end: auto; }
  .theme-toggle { order: 2; flex: 0 0 auto; margin: 0; margin-inline-start: 0; margin-inline-end: 0; }
  .nav-toggle { display: block; order: 3; flex: 0 0 auto; margin: 0; margin-inline-start: 0; }
  .search-form { order: 4; width: 100%; min-width: 0; flex-basis: 100%; margin: 0; }
  .main-nav { order: 5 !important; display: none; width: 100%; flex-basis: 100%; margin: 0; margin-inline-start: 0; margin-inline-end: 0; }
  .main-nav.open { display: block; }
  .nav-list { flex-direction: column; align-items: stretch; gap: 2px; padding: 8px 0 12px; }
  .nav-list a { padding: 11px 14px; background: rgba(255,255,255,.05); }
  .post-title { font-size: 23px; }
  .post-single { padding: 18px; }
}
@media (max-width:600px) {
  .yt-hero { flex-direction:column; text-align:center; padding:22px 18px; }
  .yt-meta h2 { font-size:22px; }
  .about-card { padding:18px; }
}
@media (max-width:520px) {
  .cards-grid { grid-template-columns:repeat(auto-fill,minmax(160px,1fr)); gap:12px; }
  .card-title { font-size:14px; }
  .section-title { font-size:18px; }
  .brand-text { font-size:18px; }
  .post-body { font-size:16px; }
}

body.script:
