(function () {
  var toggle = document.getElementById('navToggle');
  var nav = document.getElementById('mainNav');
  if (toggle && nav) {
    toggle.addEventListener('click', function () {
      if (nav.className.indexOf('open') === -1) { nav.className = nav.className + ' open'; }
      else { nav.className = nav.className.replace(' open', ''); }
    });
  }
})();
