function upgradeBloggerUrl(url) {
  if (!url) return '';
  url = url.replace(/\/(s\d+|w\d+-h\d+[^\/]*)\//, '/w800-h450-c/');
  return url;
}

function thumbUpgrade(entry) {
  var content = '';
  if (entry.content && entry.content.$t) content = entry.content.$t;
  else if (entry.summary && entry.summary.$t) content = entry.summary.$t;

  if (content) {
    var m = content.match(/(?:youtube(?:-nocookie)?\.com\/(?:embed\/|watch\?v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/);
    if (m && m[1]) {
      return 'https://i.ytimg.com/vi/' + m[1] + '/maxresdefault.jpg';
    }
  }

  if (content) {
    var imgMatch = content.match(/<img[^>]+src\s*=\s*["']([^"']+)["']/i);
    if (imgMatch && imgMatch[1]) {
      var src = imgMatch[1];
      src = src.replace(/&amp;/g, '&');
      if (src.indexOf('blogger.googleusercontent.com') !== -1 || src.indexOf('bp.blogspot.com') !== -1) {
        return upgradeBloggerUrl(src);
      }
      return src;
    }
  }

  if (!entry.media$thumbnail || !entry.media$thumbnail.url) return '';
  var url = entry.media$thumbnail.url;

  if (url.indexOf('ytimg.com') !== -1) {
    return url.replace(/\/[a-z]*default\.jpg/, '/maxresdefault.jpg');
  }

  return upgradeBloggerUrl(url);
}

function getCommentCount(entry) {
  if (entry['thr$total'] && entry['thr$total'].$t) {
    return parseInt(entry['thr$total'].$t, 10) || 0;
  }
  return 0;
}
