(function () {
  function buildCard(entry) {
    var link = '#', i;
    if (entry.link) { for (i=0;i<entry.link.length;i++){ if (entry.link[i].rel === 'alternate'){ link = entry.link[i].href; break; } } }
    var title = (entry.title && entry.title.$t) ? entry.title.$t : '';
    var thumb = thumbUpgrade(entry);
    var dateStr = '';
    if (entry.published && entry.published.$t) { dateStr = entry.published.$t.substring(0,10); }
    var comments = getCommentCount(entry);
    var art = document.createElement('article'); art.className = 'card';
    var a = document.createElement('a'); a.className = 'card-thumb'; a.href = link; a.title = title;
    if (thumb) { var img = document.createElement('img'); img.className='card-img'; img.src=thumb; img.alt=title; img.loading='lazy'; a.appendChild(img); }
    else { var ph = document.createElement('span'); ph.className='card-noimg'; ph.textContent='\u25B6'; a.appendChild(ph); }
    art.appendChild(a);
    var body = document.createElement('div'); body.className = 'card-body';
    var h3 = document.createElement('h3'); h3.className = 'card-title';
    var t = document.createElement('a'); t.href = link; t.textContent = title; h3.appendChild(t); body.appendChild(h3);
    var meta = document.createElement('div'); meta.className='card-meta';
    var ds = document.createElement('span'); ds.textContent = '\uD83D\uDCC5 ' + dateStr; meta.appendChild(ds);
    var cs = document.createElement('span'); cs.className = 'cmt'; cs.textContent = comments; meta.appendChild(cs);
    body.appendChild(meta);
    art.appendChild(body); return art;
  }
  function loadFeed(labels, containerId, max) {
    var box = document.getElementById(containerId); if (!box) return;
    function showEmpty() {
      box.innerHTML = '';
      var p = document.createElement('p');
      p.className = 'empty-msg';
      p.textContent = 'لا توجد مشاركات في هذا القسم بعد.';
      box.appendChild(p);
    }
    function tryLabel(idx) {
      if (idx >= labels.length) { showEmpty(); return; }
      var label = labels[idx];
      var cbName = 'ytcb_' + containerId.replace(/-/g,'_') + '_' + idx + '_' + Math.random().toString(36).substr(2,5);
      var done = false;
      window[cbName] = function (json) {
        if (done) return;
        done = true;
        var entries = (json && json.feed && json.feed.entry) ? json.feed.entry : [];
        if (entries.length) {
          box.innerHTML = '';
          for (var i = 0; i < entries.length; i++) { box.appendChild(buildCard(entries[i])); }
        } else { tryLabel(idx + 1); }
        try { delete window[cbName]; } catch(e) { window[cbName] = null; }
      };
      var s = document.createElement('script');
      s.src = '/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json-in-script\u0026max-results=' + max + '\u0026callback=' + cbName;
      s.async = true;
      s.onerror = function() { if (!done) { done = true; tryLabel(idx + 1); } };
      document.body.appendChild(s);
    }
    tryLabel(0);
  }
  function initFeeds() {
    loadFeed(['القرآن', 'قرآن'], 'feed-quran', 8);
    loadFeed(['حديث', 'أحاديث', 'الحديث'], 'feed-hadith', 8);
  }
  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', initFeeds); } else { initFeeds(); }
})();
