(function () {
  var area = document.getElementById('js-blog-area');
  if (!area) return;

  var path = window.location.pathname;
  var search = window.location.search;
  var pathLower = path.toLowerCase();

  if (path === '/' || path === '') { area.style.display = 'none'; return; }

  function esc(s) { return String(s).replace(/[&<>"']/g, function(c) {
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
  }); }

  function entryLink(entry) {
    var link = '#';
    if (entry.link) {
      for (var i = 0; i < entry.link.length; i++) {
        if (entry.link[i].rel === 'alternate') { link = entry.link[i].href; break; }
      }
    }
    return link;
  }

  function renderCard(entry) {
    var link = entryLink(entry);
    var title = entry.title ? entry.title.$t : '';
    var thumb = thumbUpgrade(entry);
    var date = entry.published ? entry.published.$t.substring(0,10) : '';
    var comments = getCommentCount(entry);
    return '<article class="card">' +
      '<a class="card-thumb" href="' + link + '" title="' + esc(title) + '">' +
        (thumb ? '<img class="card-img" src="' + thumb + '" alt="' + esc(title) + '" loading="lazy"/>' :
                 '<span class="card-noimg">\u25B6</span>') +
      '</a>' +
      '<div class="card-body">' +
        '<h3 class="card-title"><a href="' + link + '">' + title + '</a></h3>' +
        '<div class="card-meta">' +
          '<span>\uD83D\uDCC5 ' + date + '</span>' +
          '<span class="cmt">' + comments + '</span>' +
        '</div>' +
      '</div>' +
    '</article>';
  }

  function fetchFeed(url, cb, errCb) {
    var cbName = 'jscb_' + Math.random().toString(36).substr(2, 9);
    var timeout = setTimeout(function() {
      if (window[cbName]) { window[cbName] = null; if (errCb) errCb(); }
    }, 8000);
    window[cbName] = function(json) {
      clearTimeout(timeout);
      var entries = (json && json.feed && json.feed.entry) ? json.feed.entry : [];
      cb(entries);
      try { delete window[cbName]; } catch(e) { window[cbName] = null; }
    };
    var s = document.createElement('script');
    s.src = url + (url.indexOf('?') === -1 ? '?' : '&') + 'alt=json-in-script&callback=' + cbName;
    s.async = true;
    s.onerror = function() { clearTimeout(timeout); if (errCb) errCb(); };
    document.body.appendChild(s);
  }

  var isPostPage = /\/\d{4}\/\d{2}\/[^\/]+\.html$/.test(pathLower);
  var isLabelPage = path.indexOf('/search/label/') !== -1;
  var isSearchPage = !isLabelPage && path.indexOf('/search') !== -1 && search.indexOf('q=') !== -1;
  var isAboutPage = path.indexOf('/p/contact') !== -1 || path.indexOf('/p/about') !== -1;

  if (isAboutPage) {
    var YT_HANDLE = '%D8%B2%D9%83%D8%B1%D9%8A%D8%A7%D8%A1_%D8%A7%D9%84%D9%85%D8%B9%D8%AA%D8%B5%D9%85';
    var YT_URL = 'https://www.youtube.com/@' + YT_HANDLE;
    var YT_AVATAR = 'https://unavatar.io/youtube/@' + YT_HANDLE;

    var html = '' +
      '<article class="post-single about-page">' +
        '<h1 class="post-title">من نحن</h1>' +
        '<div class="yt-hero">' +
          '<img id="yt-avatar" src="' + YT_AVATAR + '" alt="زكرياء المعتصم" ' +
            'style="width:100px;height:100px;border-radius:50%;object-fit:cover;flex-shrink:0;display:block;background:linear-gradient(145deg,#00c76a,#06a458);box-shadow:0 8px 22px rgba(0,199,106,.45),0 0 0 4px rgba(0,199,106,.2);color:transparent;font-size:0"/>' +
          '<div class="yt-meta">' +
            '<h2>زكرياء المعتصم</h2>' +
            '<span class="yt-handle">@\u0632\u0643\u0631\u064A\u0627\u0621_\u0627\u0644\u0645\u0639\u062A\u0635\u0645</span>' +
            '<div class="yt-stats">' +
              '<span><strong id="yt-subs">463</strong> \u0645\u0634\u062A\u0631\u0643</span>' +
              '<span><strong id="yt-vids">66</strong> \u0641\u064A\u062F\u064A\u0648</span>' +
            '</div>' +
            '<a class="yt-sub-btn" href="' + YT_URL + '" target="_blank" rel="noopener">\u0627\u0634\u062A\u0631\u0643 \u0627\u0644\u0622\u0646</a>' +
          '</div>' +
        '</div>' +
        '<div class="about-card">' +
          '<h3>\u0645\u0646 \u0646\u062D\u0646</h3>' +
          '<p>\u0645\u0631\u062D\u0628\u0627\u064B \u0628\u0643\u0645 \u0641\u064A \u0642\u0646\u0627\u062A\u064A\u060C \u0645\u0639\u0643\u0645 <strong>\u0632\u0643\u0631\u064A\u0627\u0621 \u0645\u0646 \u0627\u0644\u0645\u063A\u0631\u0628 \uD83C\uDDF2\uD83C\uDDE6</strong></p>' +
          '<p>\u062A\u0647\u062F\u0641 \u0647\u0630\u0647 \u0627\u0644\u0642\u0646\u0627\u0629 \u0625\u0644\u0649 \u0646\u0634\u0631 \u0645\u062D\u062A\u0648\u0649 \u0625\u0633\u0644\u0627\u0645\u064A \u0647\u0627\u062F\u0641 \u0648\u0645\u0624\u062B\u0631\u060C \u064A\u0634\u0645\u0644:</p>' +
          '<ul class="about-list">' +
            '<li><span class="ico">\uD83D\uDCD6</span> \u0645\u0648\u0627\u0639\u0638 \u0648\u062E\u0637\u0628 \u0645\u0624\u062B\u0631\u0629 \u0644\u0643\u0628\u0627\u0631 \u0627\u0644\u0645\u0634\u0627\u064A\u062E \u0648\u0627\u0644\u0639\u0644\u0645\u0627\u0621</li>' +
            '<li><span class="ico">\uD83D\uDD4C</span> \u062A\u0644\u0627\u0648\u0629 \u062E\u0627\u0634\u0639\u0629 \u0644\u0622\u064A\u0627\u062A \u0627\u0644\u0630\u0643\u0631 \u0627\u0644\u062D\u0643\u064A\u0645 \u062A\u0631\u062A\u0627\u062D \u0644\u0647\u0627 \u0627\u0644\u0642\u0644\u0648\u0628</li>' +
            '<li><span class="ico">\uD83E\uDD32</span> \u0623\u062F\u0639\u064A\u0629 \u0648\u0623\u0630\u0643\u0627\u0631 \u0648\u0631\u0633\u0627\u0626\u0644 \u0637\u0645\u0623\u0646\u064A\u0646\u0629 \u0644\u0644\u0646\u0641\u0648\u0633 \u0627\u0644\u0645\u0636\u0637\u0631\u0628\u0629</li>' +
            '<li><span class="ico">\uD83C\uDFA7</span> \u0623\u0646\u0627\u0634\u064A\u062F \u062F\u064A\u0646\u064A\u0629 \u0647\u0627\u062F\u0626\u0629 (\u0628\u062F\u0648\u0646 \u0625\u064A\u0642\u0627\u0639)</li>' +
          '</ul>' +
          '<div class="about-quote">\u0647\u062F\u0641\u064A \u0627\u0644\u062A\u0630\u0643\u064A\u0631 \u0628\u0627\u0644\u0644\u0647 \u0633\u0628\u062D\u0627\u0646\u0647 \u0648\u062A\u0639\u0627\u0644\u0649 \u0648\u0646\u0634\u0631 \u0627\u0644\u0641\u0627\u0626\u062F\u0629\u060C \u0641\u0640 <em>"\u0627\u0644\u062F\u0627\u0644 \u0639\u0644\u0649 \u0627\u0644\u062E\u064A\u0631 \u0643\u0641\u0627\u0639\u0644\u0647"</em>.</div>' +
        '</div>' +
        '<div class="about-card">' +
          '<h3>\u0627\u062F\u0639\u0645\u0646\u0627</h3>' +
          '<p>\u0644\u0627 \u062A\u0646\u0633\u0648\u0627 \u062F\u0639\u0645\u064A \u0628\u0627\u0644\u0627\u0634\u062A\u0631\u0627\u0643 \u0641\u064A \u0627\u0644\u0642\u0646\u0627\u0629 \u0648\u062A\u0641\u0639\u064A\u0644 \u062C\u0631\u0633 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062A \uD83D\uDD14</p>' +
          '<p>\u062C\u0632\u0627\u0643\u0645 \u0627\u0644\u0644\u0647 \u062E\u064A\u0631\u0627\u064B \u0648\u062C\u0639\u0644\u0647 \u0641\u064A \u0645\u064A\u0632\u0627\u0646 \u062D\u0633\u0646\u0627\u062A\u0643\u0645.</p>' +
          '<div class="about-cta">' +
            '<p><strong>\u0627\u0634\u062A\u0631\u0643 \u0627\u0644\u0622\u0646</strong> \u0648\u0643\u0646 \u062C\u0632\u0621\u0627\u064B \u0645\u0646 \u0627\u0644\u0639\u0627\u0626\u0644\u0629</p>' +
            '<a class="yt-sub-btn" href="' + YT_URL + '" target="_blank" rel="noopener">\u0632\u064A\u0627\u0631\u0629 \u0627\u0644\u0642\u0646\u0627\u0629 \u0639\u0644\u0649 \u064A\u0648\u062A\u064A\u0648\u0628</a>' +
          '</div>' +
          '<div class="about-hashtags">' +
            '<span>#\u0632\u0643\u0631\u064A\u0627\u0621_\u0627\u0644\u0645\u0639\u062A\u0635\u0645</span>' +
            '<span>#\u0645\u0648\u0627\u0639\u0638_\u0645\u0624\u062B\u0631\u0629</span>' +
            '<span>#\u062A\u0644\u0627\u0648\u0629_\u062E\u0627\u0634\u0639\u0629</span>' +
            '<span>#\u0623\u0646\u0627\u0634\u064A\u062F_\u062F\u064A\u0646\u064A\u0629</span>' +
          '</div>' +
        '</div>' +
      '</article>';
    area.innerHTML = html;
    document.title = '\u0645\u0646 \u0646\u062D\u0646 | ' + document.title.split('|').pop().trim();

    var avEl = document.getElementById('yt-avatar');
    if (avEl) {
      var onFail = function () {
        var div = document.createElement('div');
        div.className = 'yt-avatar';
        div.textContent = '\u0632';
        if (avEl.parentNode) avEl.parentNode.replaceChild(div, avEl);
      };
      if (avEl.complete && avEl.naturalHeight === 0 && avEl.src) { onFail(); }
      else { avEl.addEventListener('error', onFail); }
    }

    (function () {
      var key = 'AIzaSyDHV-qCaUayPxXER43gW3FsHMzwZoe1eZo';
      var handle = '@' + decodeURIComponent(YT_HANDLE);
      var endpoint = 'https://www.googleapis.com/youtube/v3/channels' +
        '?part=snippet,statistics' +
        '&forHandle=' + encodeURIComponent(handle) +
        '&key=' + key;

      fetch(endpoint)
        .then(function (r) { return r.json(); })
        .then(function (data) {
          if (!data || !data.items || !data.items.length) {
            console.warn('[YT] No channel data returned.');
            return;
          }
          var ch = data.items[0];
          var stats = ch.statistics || {};
          var snip = ch.snippet || {};
          var subsEl = document.getElementById('yt-subs');
          var vidsEl = document.getElementById('yt-vids');
          if (subsEl && stats.subscriberCount) subsEl.textContent = Number(stats.subscriberCount).toLocaleString('en-US');
          if (vidsEl && stats.videoCount) vidsEl.textContent = Number(stats.videoCount).toLocaleString('en-US');
          if (snip.thumbnails) {
            var thumb = (snip.thumbnails.high || snip.thumbnails.medium || snip.thumbnails.default || {}).url;
            var img = document.getElementById('yt-avatar');
            if (thumb && img && img.src !== thumb) img.src = thumb;
          }
        })
        .catch(function (err) { console.warn('[YT] API call failed:', err); });
    })();

    return;
  }

  if (isPostPage) {
    area.innerHTML = '<div class="loading">جارٍ تحميل المشاركة...</div>';
    fetchFeed('/feeds/posts/default?max-results=500', function(entries) {
      var current = path;
      var post = null;
      for (var i = 0; i < entries.length; i++) {
        var links = entries[i].link || [];
        for (var j = 0; j < links.length; j++) {
          if (links[j].rel === 'alternate' && links[j].href.indexOf(current) !== -1) {
            post = entries[i]; break;
          }
        }
        if (post) break;
      }
      if (!post) {
        area.innerHTML = '<div class="post-single"><h1 class="post-title">المشاركة غير متاحة</h1><p class="empty-msg">لم يتم العثور على محتوى هذه المشاركة.</p></div>';
        return;
      }
      var title = post.title ? post.title.$t : '';
      var content = '';
      if (post.content && post.content.$t) content = post.content.$t;
      else if (post.summary && post.summary.$t) content = post.summary.$t;
      var published = post.published ? post.published.$t.substring(0,10) : '';
      var labels = '';
      if (post.category && post.category.length) {
        labels = post.category.map(function(c) {
          return '<a href="/search/label/' + encodeURIComponent(c.term) + '">' + esc(c.term) + '</a>';
        }).join('');
      }

      var postIdFull = post.id && post.id.$t ? post.id.$t : '';
      var postId = '';
      var blogId = '';
      var idMatch = postIdFull.match(/post-(\d+)/);
      if (idMatch) postId = idMatch[1];
      var blogMatch = postIdFull.match(/blog-(\d+)/);
      if (blogMatch) blogId = blogMatch[1];

      var commentsHtml = '';
      if (postId && blogId) {
        var commentsUrl = 'https://www.blogger.com/comment.g?blogID=' + blogId + '&postID=' + postId;
        commentsHtml = '<div class="post-comments">' +
          '<h3>\u0627\u0644\u062a\u0639\u0644\u064a\u0642\u0627\u062a</h3>' +
          '<div class="comments-cta">' +
            '<p>\u0634\u0627\u0631\u0643\u0646\u0627 \u0631\u0623\u064a\u0643 \u0648\u062a\u0639\u0644\u064a\u0642\u0643 \u0639\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0629</p>' +
            '<a class="comments-btn" href="' + commentsUrl + '" target="_blank" rel="noopener">\u0627\u0643\u062a\u0628 \u062a\u0639\u0644\u064a\u0642\u064b\u0627</a>' +
          '</div>' +
        '</div>';
      }

      area.innerHTML = '<article class="post-single">' +
        '<h1 class="post-title">' + title + '</h1>' +
        '<div class="post-meta"><span>\uD83D\uDCC5 ' + published + '</span>' + (labels ? '<span>' + labels + '</span>' : '') + '</div>' +
        '<div class="post-body">' + content + '</div>' +
        commentsHtml +
      '</article>';
      document.title = title + ' | ' + document.title.split('|').pop().trim();

    }, function() {
      area.innerHTML = '<div class="post-single"><p class="empty-msg">تعذّر تحميل المشاركة. حاول تحديث الصفحة.</p></div>';
    });
  }
  else if (isLabelPage) {
    var labelRaw = path.split('/search/label/')[1] || '';
    labelRaw = labelRaw.split('?')[0].split('#')[0];
    var labelName = decodeURIComponent(labelRaw);

    area.innerHTML = '<div class="section-head"><h2 class="section-title">' + esc(labelName) + '</h2></div>' +
      '<div class="cards-grid" id="js-label-grid"><div class="loading">جارٍ تحميل المشاركات...</div></div>';

    var variations = [labelName];
    if (labelName.indexOf('ال') === 0 && labelName.length > 2) {
      variations.push(labelName.substring(2));
    } else {
      variations.push('ال' + labelName);
    }
    variations.push(labelName.trim());

    function tryLabel(idx) {
      if (idx >= variations.length) {
        var grid = document.getElementById('js-label-grid');
        if (grid) grid.innerHTML = '<p class="empty-msg">لا توجد مشاركات في هذا القسم بعد.</p>';
        return;
      }
      var label = variations[idx];
      fetchFeed('/feeds/posts/default/-/' + encodeURIComponent(label) + '?max-results=24', function(entries) {
        if (entries.length) {
          var grid = document.getElementById('js-label-grid');
          if (grid) grid.innerHTML = entries.map(renderCard).join('');
        } else { tryLabel(idx + 1); }
      }, function() { tryLabel(idx + 1); });
    }
    tryLabel(0);
  }
  else if (isSearchPage) {
    var q = search.split('q=')[1].split('&')[0];
    q = decodeURIComponent(q.replace(/\+/g, ' '));
    area.innerHTML = '<div class="section-head"><h2 class="section-title">نتائج البحث عن: ' + esc(q) + '</h2></div>' +
      '<div class="cards-grid" id="js-search-grid"><div class="loading">جارٍ البحث...</div></div>';
    fetchFeed('/feeds/posts/default?q=' + encodeURIComponent(q) + '&max-results=24', function(entries) {
      var grid = document.getElementById('js-search-grid');
      if (!entries.length) { grid.innerHTML = '<p class="empty-msg">لا توجد نتائج مطابقة.</p>'; return; }
      grid.innerHTML = entries.map(renderCard).join('');
    }, function() {
      var grid = document.getElementById('js-search-grid');
      if (grid) grid.innerHTML = '<p class="empty-msg">تعذّر البحث.</p>';
    });
  }
  else {
    area.innerHTML = '<div class="section-head"><h2 class="section-title">المشاركات</h2></div>' +
      '<div class="cards-grid" id="js-default-grid"><div class="loading">جارٍ التحميل...</div></div>';
    fetchFeed('/feeds/posts/default?max-results=24', function(entries) {
      var grid = document.getElementById('js-default-grid');
      if (!entries.length) { grid.innerHTML = '<p class="empty-msg">لا توجد مشاركات.</p>'; return; }
      grid.innerHTML = entries.map(renderCard).join('');
    }, function() {
      var grid = document.getElementById('js-default-grid');
      if (grid) grid.innerHTML = '<p class="empty-msg">تعذّر تحميل المشاركات.</p>';
    });
  }
})();
