(function () {
  'use strict';
  function proxied(url) {
    if (!url) return url;
    if (url.indexOf('wsrv.nl') !== -1) return url;
    if (!/^https?:\/\//i.test(url)) return url;
    var clean = url.replace(/^https?:\/\//i, '');
    return 'https://wsrv.nl/?url=' + encodeURIComponent(clean) + '&n=-1';
  }
  function triggerDownload(href, filename) {
    fetch(proxied(href), { mode: 'cors', credentials: 'omit' })
      .then(function (r) { if (!r.ok) throw new Error('proxy HTTP ' + r.status); return r.blob(); })
      .then(function (blob) {
        var u = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.href = u; a.download = filename || 'image.jpg';
        a.style.display = 'none';
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        setTimeout(function () { URL.revokeObjectURL(u); }, 2000);
      })
      .catch(function (err) { console.warn('[download] failed:', err); window.open(href, '_blank', 'noopener'); });
  }
  function bind() {
    var links = document.querySelectorAll('.download-links a[href]');
    for (var i = 0; i < links.length; i++) {
      (function (a) {
        if (a.getAttribute('data-dl-bound') === '1') return;
        a.setAttribute('data-dl-bound', '1');
        a.addEventListener('click', function (e) {
          e.preventDefault(); e.stopPropagation();
          var href = a.getAttribute('href') || '';
          if (!href || href.charAt(0) === '#') return;
          triggerDownload(href, a.getAttribute('download') || 'image.jpg');
          return false;
        }, true);
      })(links[i]);
    }
  }
  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', bind); } else { bind(); }
  try { new MutationObserver(bind).observe(document.body, { childList: true, subtree: true }); } catch (e) {}
})();
