(function () {
  'use strict';

  var siteUrl = window.location.origin;
  var currentUrl = window.location.href;

  function injectJSONLD(obj, tag) {
    if (tag && document.querySelector('script[data-schema="' + tag + '"]')) return;
    var s = document.createElement('script');
    s.type = 'application/ld+json';
    if (tag) s.setAttribute('data-schema', tag);
    s.textContent = JSON.stringify(obj);
    document.head.appendChild(s);
  }

  injectJSONLD({
    '@context': 'https://schema.org',
    '@type': 'WebSite',
    'name': 'زكرياء المعتصم',
    'alternateName': 'مدونة إسلامية بالفيديو',
    'url': siteUrl,
    'inLanguage': 'ar',
    'potentialAction': {
      '@type': 'SearchAction',
      'target': { '@type': 'EntryPoint', 'urlTemplate': siteUrl + '/search?q={search_term_string}' },
      'query-input': 'required name=search_term_string'
    }
  }, 'website');

  injectJSONLD({
    '@context': 'https://schema.org',
    '@type': 'Organization',
    'name': 'زكرياء المعتصم',
    'url': siteUrl,
    'logo': { '@type': 'ImageObject', 'url': siteUrl + '/favicon.ico', 'width': 512, 'height': 512 },
    'sameAs': ['https://www.youtube.com/@%D8%B2%D9%83%D8%B1%D9%8A%D8%A7%D8%A1_%D8%A7%D9%84%D9%85%D8%B9%D8%AA%D8%B5%D9%85']
  }, 'organization');

  function addPostSchema() {
    if (document.querySelector('script[data-schema="posting"]')) return true;
    var titleEl = document.querySelector('.post-title');
    if (!titleEl) return false;

    var title = titleEl.textContent.trim();
    var bodyEl = document.querySelector('.post-single .post-body');
    var images = [];
    if (bodyEl) {
      var imgs = bodyEl.querySelectorAll('img');
      for (var i = 0; i < imgs.length && images.length < 3; i++) {
        var src = imgs[i].src || '';
        if (src && src.indexOf('data:') !== 0) images.push(src);
      }
    }
    var dateStr = '';
    var dateEl = document.querySelector('.post-meta span');
    if (dateEl) {
      var m = dateEl.textContent.match(/(\d{4}-\d{2}-\d{2})/);
      if (m) dateStr = m[1];
    }
    var dateISO = dateStr ? new Date(dateStr).toISOString() : new Date().toISOString();
    var labelEls = document.querySelectorAll('.post-meta a');
    var keywords = [];
    for (var k = 0; k < labelEls.length; k++) {
      var t = labelEls[k].textContent.trim();
      if (t) keywords.push(t);
    }

    var schema = {
      '@context': 'https://schema.org',
      '@type': 'BlogPosting',
      'mainEntityOfPage': { '@type': 'WebPage', '@id': currentUrl },
      'headline': title,
      'name': title,
      'description': title,
      'inLanguage': 'ar',
      'author': { '@type': 'Person', 'name': 'زكرياء المعتصم', 'url': siteUrl },
      'publisher': {
        '@type': 'Organization',
        'name': 'زكرياء المعتصم',
        'logo': { '@type': 'ImageObject', 'url': siteUrl + '/favicon.ico', 'width': 512, 'height': 512 }
      },
      'datePublished': dateISO,
      'dateModified': dateISO,
      'url': currentUrl,
      'isPartOf': { '@type': 'Blog', 'name': 'زكرياء المعتصم', 'url': siteUrl }
    };
    if (images.length) schema.image = images;
    if (keywords.length) schema.keywords = keywords.join(', ');

    injectJSONLD(schema, 'posting');
    return true;
  }

  function addBreadcrumb() {
    if (document.querySelector('script[data-schema="breadcrumb"]')) return true;
    var titleEl = document.querySelector('.post-title');
    if (!titleEl) return false;

    injectJSONLD({
      '@context': 'https://schema.org',
      '@type': 'BreadcrumbList',
      'itemListElement': [
        { '@type': 'ListItem', 'position': 1, 'name': 'الرئيسية', 'item': siteUrl },
        { '@type': 'ListItem', 'position': 2, 'name': titleEl.textContent.trim(), 'item': currentUrl }
      ]
    }, 'breadcrumb');
    return true;
  }

  var tries = 0;
  var timer = setInterval(function () {
    var a = addPostSchema();
    var b = addBreadcrumb();
    if ((a && b) || ++tries > 30) clearInterval(timer);
  }, 500);
})();
